export async function getDashboardData() {
  try {
    const [analytics, notifications, settings] = await Promise.all([
      fetch('http://localhost:3000/api/analytics').then(r => r.json()),
      fetch('http://localhost:3000/api/notifications').then(r => r.json()),
      fetch('http://localhost:3000/api/settings').then(r => r.json())
    ]);

    return { analytics, notifications, settings };
  } catch {
    // Return mock data for build time or missing API
    return {
      analytics: { views: 500, clicks: 120 },
      notifications: [{ id: 1, message: 'Welcome to the dashboard!' }],
      settings: { theme: 'dark', notificationsEnabled: true }
    };
  }
}

export default async function Dashboard() {
  const { analytics, notifications, settings } = await getDashboardData();

  return (
    <div>
      <h2>Dashboard Content</h2>

      <div className="analytics-section">
        <h3>Analytics</h3>
        <p>Views: {analytics.views}</p>
        <p>Clicks: {analytics.clicks}</p>
      </div>

      <div className="notifications-section">
        <h3>Notifications</h3>
        <ul>
          {notifications.map((notification: any) => (
            <li key={notification.id}>{notification.message}</li>
          ))}
        </ul>
      </div>

      <div className="settings-section">
        <h3>Settings</h3>
        <p>Theme: {settings.theme}</p>
        <p>Notifications: {settings.notificationsEnabled ? 'Enabled' : 'Disabled'}</p>
      </div>
    </div>
  );
}
